#[allow(non_camel_case_types, reason = "schema names are preserved")]
#[allow(non_snake_case, reason = "schema field names are preserved")]
#[derive(Debug, Clone, PartialEq)]
pub struct File {
    pub header: SoxHeader,
    pub records: ::std::vec::Vec<TroopInfoRecord>,
    pub footer: [u8; 64],
}

impl File {
    #[allow(non_snake_case, reason = "schema field names are preserved")]
    #[allow(clippy::too_many_lines, reason = "schema methods follow field order")]
    pub fn parse(buf: &[u8], offset: &mut usize) -> ::std::result::Result<Self, Error> {
        let header = SoxHeader::parse(buf, offset)?;
        let records = {
            let raw_count = header.record_count;
            #[allow(
                clippy::unnecessary_fallible_conversions,
                reason = "length fields can use signed or wide integer types"
            )]
            let count = usize::try_from(raw_count).map_err(|_| Error::InvalidLength {
                field: "records",
                value: i128::from(raw_count),
            })?;
            let mut values = ::std::vec::Vec::with_capacity(count);
            for _ in 0..count {
                values.push(TroopInfoRecord::parse(buf, offset)?);
            }
            values
        };
        let footer = {
            let bytes = self::take(buf, offset, 64)?;
            <[u8; 64]>::try_from(bytes).map_err(|_| Error::FixedSize {
                field: "footer",
                expected: 64,
                actual: bytes.len(),
            })?
        };
        Ok(Self {
            header,
            records,
            footer,
        })
    }
}

impl File {
    #[allow(non_snake_case, reason = "schema field names are preserved")]
    #[allow(clippy::too_many_lines, reason = "schema methods follow field order")]
    pub fn to_bytes(&self) -> ::std::result::Result<::std::vec::Vec<u8>, Error> {
        let mut buf = ::std::vec::Vec::new();
        let value = &self.header;
        buf.extend_from_slice(&value.to_bytes()?);
        let value = &self.records;
        for item in value {
            buf.extend_from_slice(&item.to_bytes()?);
        }
        let value = &self.footer;
        buf.extend_from_slice(value);
        Ok(buf)
    }
}

impl File {
    #[allow(non_snake_case, reason = "schema field names are preserved")]
    #[allow(clippy::too_many_lines, reason = "schema methods follow field order")]
    pub fn to_json(&self) -> ::std::string::String {
        let mut json = ::std::string::String::from("{");
        write_json_string(&mut json, "header");
        json.push(':');
        let value = &self.header;
        json.push_str(&value.to_json());
        json.push(',');
        write_json_string(&mut json, "records");
        json.push(':');
        let value = &self.records;
        json.push('[');
        for (index, item) in value.iter().enumerate() {
            if index > 0 {
                json.push(',');
            }
            let value = item;
            json.push_str(&value.to_json());
        }
        json.push(']');
        json.push(',');
        write_json_string(&mut json, "footer");
        json.push(':');
        let value = &self.footer;
        json.push('[');
        for (index, item) in value.iter().enumerate() {
            if index > 0 {
                json.push(',');
            }
            let value = item;
            json.push_str(&value.to_string());
        }
        json.push(']');
        json.push('}');
        json
    }
}
